contracts/core/CarbonCreditNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title CarbonCreditNFT
 * @notice Core carbon credit asset registry - Each NFT represents verified CO2 reduction
 * @dev ERC-721 with oracle-verified metadata and retirement mechanism
 * 
 * Key Features:
 * - Oracle-backed minting (Chainlink proof required)
 * - Double-counting prevention (serial number hashing)
 * - Permanent retirement with audit trail
 * - Multi-methodology support (ICM/Verra/Gold Standard)
 * - Batch operations for gas optimization
 */
contract CarbonCreditNFT is 
    ERC721URIStorage, 
    ERC721Enumerable,
    AccessControl, 
    Pausable,
    ReentrancyGuard 
{
    using Counters for Counters.Counter;

    // ============ ROLES ============
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant ISSUER_ROLE = keccak256("ISSUER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    // ============ STATE VARIABLES ============
    Counters.Counter private _tokenIds;
    
    /// @notice Carbon credit metadata structure
    struct CarbonCredit {
        string projectId;              // Unique project identifier
        string projectName;            // Human-readable project name
        string methodology;            // "ICM_COMPLIANCE" | "VERRA_VCS" | "GOLD_STANDARD"
        uint256 co2Tonnes;            // Carbon offset amount (18 decimals)
        uint256 vintageYear;          // Year of emission reduction
        string geography;              // Country/region code (ISO 3166)
        bytes32 oracleProofHash;      // Chainlink oracle attestation
        string satelliteDataCID;       // IPFS CID for satellite verification
        address verificationSource;    // ACVA/Verra verifier address
        uint256 verificationDate;     // Timestamp of verification
        bool isRetired;               // Retirement status
        uint256 issuanceDate;         // Minting timestamp
        string serialNumber;          // External registry serial (if applicable)
    }

    /// @notice Retirement certificate for ESG reporting
    struct RetirementCertificate {
        uint256 originalTokenId;
        address retiredBy;
        uint256 retirementDate;
        string retirementReason;
        uint256 co2Tonnes;
    }

    // ============ MAPPINGS ============
    mapping(uint256 => CarbonCredit) public credits;
    mapping(bytes32 => bool) public issuedSerials;           // Prevent double-counting
    mapping(uint256 => RetirementCertificate) public retirementCertificates;
    mapping(string => uint256[]) public projectCredits;      // projectId => tokenIds
    mapping(address => uint256) public userRetiredTonnes;    // ESG tracking
    
    // ============ GLOBAL STATS ============
    uint256 public totalMintedTonnes;
    uint256 public totalRetiredTonnes;
    uint256 public totalActiveCredits;
    
    // Methodology-specific counters
    mapping(string => uint256) public methodologyTonnes;     // "VERRA_VCS" => total tonnes

    // ============ EVENTS ============
    event CreditMinted(
        uint256 indexed tokenId,
        string indexed projectId,
        address indexed recipient,
        uint256 co2Tonnes,
        string methodology
    );
    
    event CreditRetired(
        uint256 indexed tokenId,
        address indexed retiredBy,
        uint256 timestamp,
        uint256 co2Tonnes,
        string reason
    );
    
    event CreditBatchMinted(
        uint256[] tokenIds,
        string projectId,
        uint256 totalTonnes
    );
    
    event VerificationUpdated(
        uint256 indexed tokenId,
        address verifier,
        bytes32 newProofHash
    );

    event SerialNumberRegistered(
        bytes32 indexed serialHash,
        string serialNumber,
        uint256 tokenId
    );

    // ============ CONSTRUCTOR ============
    constructor() ERC721("ATMOS Carbon Credit", "ACC") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
    }

    // ============ CORE FUNCTIONS ============

    /**
     * @notice Mint a single carbon credit with oracle verification
     * @dev Only callable by addresses with ISSUER_ROLE
     * @param to Recipient address
     * @param projectId Unique project identifier
     * @param serialNumber External registry serial (e.g., "VCS-12345")
     * @param methodology Carbon standard methodology
     * @param co2Tonnes Amount of CO2 offset (18 decimals: 1000e18 = 1000 tonnes)
     * @param vintageYear Year of emission reduction
     * @param geography ISO 3166 country code
     * @param oracleProofHash Chainlink oracle attestation hash
     * @param tokenURI IPFS metadata URI
     * @return tokenId The newly minted token ID
     */
    function mintCredit(
        address to,
        string memory projectId,
        string memory projectName,
        string memory serialNumber,
        string memory methodology,
        uint256 co2Tonnes,
        uint256 vintageYear,
        string memory geography,
        bytes32 oracleProofHash,
        string memory satelliteDataCID,
        string memory tokenURI
    ) 
        external 
        onlyRole(ISSUER_ROLE) 
        whenNotPaused
        nonReentrant
        returns (uint256) 
    {
        require(to != address(0), "Invalid recipient");
        require(co2Tonnes > 0, "Invalid CO2 amount");
        require(vintageYear >= 2015 && vintageYear <= 2050, "Invalid vintage year");
        require(oracleProofHash != bytes32(0), "Oracle proof required");

        // Prevent double-counting across registries
        bytes32 serialHash = keccak256(abi.encodePacked(methodology, serialNumber));
        require(!issuedSerials[serialHash], "Credit already tokenized");

        _tokenIds.increment();
        uint256 newTokenId = _tokenIds.current();

        // Mint NFT
        _safeMint(to, newTokenId);
        _setTokenURI(newTokenId, tokenURI);

        // Store metadata
        credits[newTokenId] = CarbonCredit({
            projectId: projectId,
            projectName: projectName,
            methodology: methodology,
            co2Tonnes: co2Tonnes,
            vintageYear: vintageYear,
            geography: geography,
            oracleProofHash: oracleProofHash,
            satelliteDataCID: satelliteDataCID,
            verificationSource: msg.sender,
            verificationDate: block.timestamp,
            isRetired: false,
            issuanceDate: block.timestamp,
            serialNumber: serialNumber
        });

        // Mark serial as used
        issuedSerials[serialHash] = true;

        // Update global stats
        totalMintedTonnes += co2Tonnes;
        totalActiveCredits++;
        methodologyTonnes[methodology] += co2Tonnes;
        
        // Index by project
        projectCredits[projectId].push(newTokenId);

        emit CreditMinted(newTokenId, projectId, to, co2Tonnes, methodology);
        emit SerialNumberRegistered(serialHash, serialNumber, newTokenId);

        return newTokenId;
    }

    /**
     * @notice Batch mint carbon credits for gas optimization
     * @dev Use for large project issuances (e.g., 100+ credits)
     * @param to Recipient address
     * @param projectId Shared project identifier
     * @param credits_ Array of credit data structs
     * @return tokenIds Array of newly minted token IDs
     */
    function batchMint(
        address to,
        string memory projectId,
        CreditData[] calldata credits_
    ) 
        external 
        onlyRole(ISSUER_ROLE) 
        whenNotPaused
        nonReentrant
        returns (uint256[] memory tokenIds) 
    {
        require(credits_.length > 0 && credits_.length <= 100, "Invalid batch size");
        
        tokenIds = new uint256[](credits_.length);
        uint256 totalBatchTonnes = 0;

        for (uint256 i = 0; i < credits_.length; i++) {
            CreditData calldata data = credits_[i];
            
            bytes32 serialHash = keccak256(abi.encodePacked(data.methodology, data.serialNumber));
            require(!issuedSerials[serialHash], "Duplicate serial in batch");

            _tokenIds.increment();
            uint256 tokenId = _tokenIds.current();
            tokenIds[i] = tokenId;

            _safeMint(to, tokenId);
            _setTokenURI(tokenId, data.tokenURI);

            credits[tokenId] = CarbonCredit({
                projectId: projectId,
                projectName: data.projectName,
                methodology: data.methodology,
                co2Tonnes: data.co2Tonnes,
                vintageYear: data.vintageYear,
                geography: data.geography,
                oracleProofHash: data.oracleProofHash,
                satelliteDataCID: data.satelliteDataCID,
                verificationSource: msg.sender,
                verificationDate: block.timestamp,
                isRetired: false,
                issuanceDate: block.timestamp,
                serialNumber: data.serialNumber
            });

            issuedSerials[serialHash] = true;
            totalBatchTonnes += data.co2Tonnes;
            methodologyTonnes[data.methodology] += data.co2Tonnes;
            projectCredits[projectId].push(tokenId);
        }

        totalMintedTonnes += totalBatchTonnes;
        totalActiveCredits += credits_.length;

        emit CreditBatchMinted(tokenIds, projectId, totalBatchTonnes);

        return tokenIds;
    }

    /**
     * @notice Retire (burn) a carbon credit for offsetting
     * @dev Emits retirement certificate for ESG reporting
     * @param tokenId Token to retire
     * @param reason Retirement reason (e.g., "Q1 2026 Corporate Offsetting")
     */
    function retireCredit(uint256 tokenId, string memory reason) 
        external 
        nonReentrant
    {
        require(ownerOf(tokenId) == msg.sender, "Not credit owner");
        require(!credits[tokenId].isRetired, "Already retired");
        require(bytes(reason).length > 0, "Reason required");

        CarbonCredit storage credit = credits[tokenId];
        credit.isRetired = true;

        // Create retirement certificate
        retirementCertificates[tokenId] = RetirementCertificate({
            originalTokenId: tokenId,
            retiredBy: msg.sender,
            retirementDate: block.timestamp,
            retirementReason: reason,
            co2Tonnes: credit.co2Tonnes
        });

        // Update global stats
        totalRetiredTonnes += credit.co2Tonnes;
        totalActiveCredits--;
        userRetiredTonnes[msg.sender] += credit.co2Tonnes;

        emit CreditRetired(tokenId, msg.sender, block.timestamp, credit.co2Tonnes, reason);

        // Burn NFT (permanent destruction)
        _burn(tokenId);
    }

    /**
     * @notice Batch retirement for enterprises (gas-optimized)
     * @param tokenIds Array of token IDs to retire
     * @param reason Shared retirement reason
     */
    function batchRetire(uint256[] calldata tokenIds, string memory reason) 
        external 
        nonReentrant
    {
        require(tokenIds.length > 0 && tokenIds.length <= 50, "Invalid batch size");
        
        uint256 totalRetiredBatch = 0;

        for (uint256 i = 0; i < tokenIds.length; i++) {
            uint256 tokenId = tokenIds[i];
            require(ownerOf(tokenId) == msg.sender, "Not owner");
            require(!credits[tokenId].isRetired, "Already retired");

            CarbonCredit storage credit = credits[tokenId];
            credit.isRetired = true;

            retirementCertificates[tokenId] = RetirementCertificate({
                originalTokenId: tokenId,
                retiredBy: msg.sender,
                retirementDate: block.timestamp,
                retirementReason: reason,
                co2Tonnes: credit.co2Tonnes
            });

            totalRetiredBatch += credit.co2Tonnes;
            
            emit CreditRetired(tokenId, msg.sender, block.timestamp, credit.co2Tonnes, reason);
            
            _burn(tokenId);
        }

        totalRetiredTonnes += totalRetiredBatch;
        totalActiveCredits -= tokenIds.length;
        userRetiredTonnes[msg.sender] += totalRetiredBatch;
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @notice Get comprehensive credit information
     */
    function getCreditDetails(uint256 tokenId) 
        external 
        view 
        returns (CarbonCredit memory) 
    {
        require(_exists(tokenId), "Token does not exist");
        return credits[tokenId];
    }

    /**
     * @notice Get all credits for a specific project
     */
    function getProjectCredits(string memory projectId) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return projectCredits[projectId];
    }

    /**
     * @notice Get user's retirement certificate for ESG reporting
     */
    function getRetirementCertificate(uint256 tokenId) 
        external 
        view 
        returns (RetirementCertificate memory) 
    {
        require(retirementCertificates[tokenId].retiredBy != address(0), "Not retired");
        return retirementCertificates[tokenId];
    }

    /**
     * @notice Get global carbon statistics
     */
    function getGlobalStats() 
        external 
        view 
        returns (
            uint256 minted,
            uint256 retired,
            uint256 active,
            uint256 totalTokens
        ) 
    {
        return (
            totalMintedTonnes,
            totalRetiredTonnes,
            totalActiveCredits,
            _tokenIds.current()
        );
    }

    /**
     * @notice Get methodology-specific statistics
     */
    function getMethodologyStats(string memory methodology) 
        external 
        view 
        returns (uint256 totalTonnes) 
    {
        return methodologyTonnes[methodology];
    }

    /**
     * @notice Verify if a serial number has been tokenized (anti-fraud)
     */
    function isSerialTokenized(string memory methodology, string memory serialNumber) 
        external 
        view 
        returns (bool) 
    {
        bytes32 serialHash = keccak256(abi.encodePacked(methodology, serialNumber));
        return issuedSerials[serialHash];
    }

    // ============ ADMIN FUNCTIONS ============

    /**
     * @notice Emergency pause (e.g., oracle compromise detected)
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @notice Update oracle proof (e.g., reverification after audit)
     */
    function updateVerification(
        uint256 tokenId,
        bytes32 newProofHash,
        string memory newSatelliteCID
    ) 
        external 
        onlyRole(ORACLE_ROLE) 
    {
        require(_exists(tokenId), "Token does not exist");
        
        credits[tokenId].oracleProofHash = newProofHash;
        credits[tokenId].satelliteDataCID = newSatelliteCID;
        credits[tokenId].verificationDate = block.timestamp;

        emit VerificationUpdated(tokenId, msg.sender, newProofHash);
    }

    // ============ REQUIRED OVERRIDES ============

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 tokenId,
        uint256 batchSize
    ) internal override(ERC721, ERC721Enumerable) whenNotPaused {
        super._beforeTokenTransfer(from, to, tokenId, batchSize);
    }

    function _burn(uint256 tokenId) 
        internal 
        override(ERC721, ERC721URIStorage) 
    {
        super._burn(tokenId);
    }

    function tokenURI(uint256 tokenId) 
        public 
        view 
        override(ERC721, ERC721URIStorage) 
        returns (string memory) 
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721URIStorage, ERC721Enumerable, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

// ============ HELPER STRUCT FOR BATCH MINTING ============
struct CreditData {
    string projectName;
    string serialNumber;
    string methodology;
    uint256 co2Tonnes;
    uint256 vintageYear;
    string geography;
    bytes32 oracleProofHash;
    string satelliteDataCID;
    string tokenURI;
}

contracts/core/CarbonCreditToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./CarbonCreditNFT.sol";

/**
 * @title CarbonCreditToken (CCT)
 * @notice ERC-20 wrapper for carbon credit NFTs to enable AMM trading
 * @dev NFTs are locked in this contract → CCT minted 1:1 by CO2 tonnes
 * 
 * Key Features:
 * - 1 CCT = 1 tonne CO2 offset
 * - NFTs remain locked until unwrapped
 * - Separate pools for different methodologies (ICM/Verra/Gold Standard)
 * - Transparent backing - users can query which NFTs back their tokens
 */
contract CarbonCreditToken is 
    ERC20, 
    ERC20Burnable,
    AccessControl, 
    Pausable,
    ReentrancyGuard 
{
    bytes32 public constant WRAPPER_ROLE = keccak256("WRAPPER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    // ============ STATE VARIABLES ============
    
    /// @notice Reference to underlying NFT contract
    CarbonCreditNFT public immutable nftContract;
    
    /// @notice Methodology filter (e.g., "VERRA_VCS" for CCT-VCS token)
    string public methodology;
    
    /// @notice Mapping of wrapped NFTs: tokenId => isWrapped
    mapping(uint256 => bool) public wrappedNFTs;
    
    /// @notice User's wrapped NFT holdings: user => tokenIds[]
    mapping(address => uint256[]) private userWrappedNFTs;
    
    /// @notice Reverse lookup: tokenId => array index in userWrappedNFTs
    mapping(uint256 => uint256) private nftIndexInUserArray;
    
    /// @notice Total number of NFTs wrapped
    uint256 public totalNFTsWrapped;
    
    /// @notice Total CO2 tonnes represented by this token
    uint256 public totalTonnesWrapped;

    // ============ EVENTS ============
    
    event CreditWrapped(
        address indexed user,
        uint256 indexed tokenId,
        uint256 co2Tonnes
    );
    
    event CreditUnwrapped(
        address indexed user,
        uint256 indexed tokenId,
        uint256 co2Tonnes
    );
    
    event BatchWrapped(
        address indexed user,
        uint256[] tokenIds,
        uint256 totalTonnes
    );

    // ============ CONSTRUCTOR ============
    
    /**
     * @param name_ Token name (e.g., "ATMOS Carbon Credit - Verra")
     * @param symbol_ Token symbol (e.g., "CCT-VCS")
     * @param nftContract_ Address of CarbonCreditNFT contract
     * @param methodology_ Carbon standard filter (e.g., "VERRA_VCS")
     */
    constructor(
        string memory name_,
        string memory symbol_,
        address nftContract_,
        string memory methodology_
    ) ERC20(name_, symbol_) {
        require(nftContract_ != address(0), "Invalid NFT contract");
        
        nftContract = CarbonCreditNFT(nftContract_);
        methodology = methodology_;
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(WRAPPER_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
    }

    // ============ CORE FUNCTIONS ============

    /**
     * @notice Wrap a carbon credit NFT into fungible tokens
     * @dev NFT is transferred to this contract and locked
     * @param tokenId NFT token ID to wrap
     * @return tonnesMinted Amount of CCT minted (equals NFT's co2Tonnes)
     */
    function wrapCredit(uint256 tokenId) 
        external 
        whenNotPaused
        nonReentrant
        returns (uint256 tonnesMinted) 
    {
        require(nftContract.ownerOf(tokenId) == msg.sender, "Not NFT owner");
        require(!wrappedNFTs[tokenId], "Already wrapped");

        // Get credit details
        CarbonCreditNFT.CarbonCredit memory credit = nftContract.getCreditDetails(tokenId);
        
        // Verify methodology matches this token pool
        require(
            keccak256(abi.encodePacked(credit.methodology)) == 
            keccak256(abi.encodePacked(methodology)),
            "Methodology mismatch"
        );
        
        require(!credit.isRetired, "Cannot wrap retired credit");

        // Transfer NFT to this contract (lock)
        nftContract.transferFrom(msg.sender, address(this), tokenId);

        // Mark as wrapped
        wrappedNFTs[tokenId] = true;
        
        // Add to user's wrapped NFT list
        userWrappedNFTs[msg.sender].push(tokenId);
        nftIndexInUserArray[tokenId] = userWrappedNFTs[msg.sender].length - 1;
        
        // Update stats
        totalNFTsWrapped++;
        totalTonnesWrapped += credit.co2Tonnes;

        // Mint ERC-20 tokens (1 tonne = 1e18 tokens)
        tonnesMinted = credit.co2Tonnes;
        _mint(msg.sender, tonnesMinted);

        emit CreditWrapped(msg.sender, tokenId, tonnesMinted);

        return tonnesMinted;
    }

    /**
     * @notice Batch wrap multiple NFTs (gas-optimized)
     * @param tokenIds Array of NFT token IDs
     * @return totalMinted Total CCT tokens minted
     */
    function batchWrap(uint256[] calldata tokenIds) 
        external 
        whenNotPaused
        nonReentrant
        returns (uint256 totalMinted) 
    {
        require(tokenIds.length > 0 && tokenIds.length <= 50, "Invalid batch size");
        
        totalMinted = 0;

        for (uint256 i = 0; i < tokenIds.length; i++) {
            uint256 tokenId = tokenIds[i];
            
            require(nftContract.ownerOf(tokenId) == msg.sender, "Not NFT owner");
            require(!wrappedNFTs[tokenId], "Already wrapped");

            CarbonCreditNFT.CarbonCredit memory credit = nftContract.getCreditDetails(tokenId);
            
            require(
                keccak256(abi.encodePacked(credit.methodology)) == 
                keccak256(abi.encodePacked(methodology)),
                "Methodology mismatch"
            );
            
            require(!credit.isRetired, "Cannot wrap retired credit");

            nftContract.transferFrom(msg.sender, address(this), tokenId);
            
            wrappedNFTs[tokenId] = true;
            userWrappedNFTs[msg.sender].push(tokenId);
            nftIndexInUserArray[tokenId] = userWrappedNFTs[msg.sender].length - 1;
            
            totalMinted += credit.co2Tonnes;
        }

        totalNFTsWrapped += tokenIds.length;
        totalTonnesWrapped += totalMinted;

        _mint(msg.sender, totalMinted);

        emit BatchWrapped(msg.sender, tokenIds, totalMinted);

        return totalMinted;
    }

    /**
     * @notice Unwrap fungible tokens back into a specific NFT
     * @dev Burns CCT tokens and returns locked NFT
     * @param tokenId NFT token ID to unwrap
     * @return tonnesBurned Amount of CCT burned
     */
    function unwrapCredit(uint256 tokenId) 
        external 
        nonReentrant
        returns (uint256 tonnesBurned) 
    {
        require(wrappedNFTs[tokenId], "NFT not wrapped");
        
        CarbonCreditNFT.CarbonCredit memory credit = nftContract.getCreditDetails(tokenId);
        tonnesBurned = credit.co2Tonnes;
        
        require(balanceOf(msg.sender) >= tonnesBurned, "Insufficient CCT balance");

        // Burn CCT tokens
        _burn(msg.sender, tonnesBurned);

        // Mark as unwrapped
        wrappedNFTs[tokenId] = false;
        
        // Remove from user's wrapped list (if they're the original wrapper)
        _removeFromUserArray(msg.sender, tokenId);
        
        // Update stats
        totalNFTsWrapped--;
        totalTonnesWrapped -= tonnesBurned;

        // Transfer NFT back to user
        nftContract.transferFrom(address(this), msg.sender, tokenId);

        emit CreditUnwrapped(msg.sender, tokenId, tonnesBurned);

        return tonnesBurned;
    }

    /**
     * @notice Unwrap any available NFT (for users who bought CCT on AMM)
     * @dev Unwraps first available NFT from contract's holdings
     * @param amount Amount of CCT to unwrap (must match an NFT's tonnes exactly)
     */
    function unwrapAny(uint256 amount) 
        external 
        nonReentrant
        returns (uint256 tokenId) 
    {
        require(balanceOf(msg.sender) >= amount, "Insufficient balance");
        require(totalNFTsWrapped > 0, "No NFTs available");

        // Find an NFT matching the requested amount
        tokenId = _findMatchingNFT(amount);
        require(tokenId != 0, "No matching NFT found");

        // Burn CCT
        _burn(msg.sender, amount);

        // Update state
        wrappedNFTs[tokenId] = false;
        totalNFTsWrapped--;
        totalTonnesWrapped -= amount;

        // Transfer NFT
        nftContract.transferFrom(address(this), msg.sender, tokenId);

        emit CreditUnwrapped(msg.sender, tokenId, amount);

        return tokenId;
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @notice Get all NFTs wrapped by a user
     */
    function getUserWrappedNFTs(address user) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return userWrappedNFTs[user];
    }

    /**
     * @notice Get total backing (transparency check)
     */
    function getBackingInfo() 
        external 
        view 
        returns (
            uint256 nftsLocked,
            uint256 tonnesLocked,
            uint256 tokensCirculating
        ) 
    {
        return (
            totalNFTsWrapped,
            totalTonnesWrapped,
            totalSupply()
        );
    }

    /**
     * @notice Verify 1:1 backing ratio
     */
    function isFullyBacked() external view returns (bool) {
        return totalSupply() == totalTonnesWrapped;
    }

    // ============ INTERNAL HELPERS ============

    function _removeFromUserArray(address user, uint256 tokenId) private {
        uint256 index = nftIndexInUserArray[tokenId];
        uint256 lastIndex = userWrappedNFTs[user].length - 1;

        if (index != lastIndex) {
            uint256 lastTokenId = userWrappedNFTs[user][lastIndex];
            userWrappedNFTs[user][index] = lastTokenId;
            nftIndexInUserArray[lastTokenId] = index;
        }

        userWrappedNFTs[user].pop();
        delete nftIndexInUserArray[tokenId];
    }

    function _findMatchingNFT(uint256 targetAmount) 
        private 
        view 
        returns (uint256) 
    {
        uint256 totalTokens = nftContract.totalSupply();
        
        for (uint256 i = 1; i <= totalTokens; i++) {
            if (wrappedNFTs[i] && nftContract.ownerOf(i) == address(this)) {
                CarbonCreditNFT.CarbonCredit memory credit = nftContract.getCreditDetails(i);
                if (credit.co2Tonnes == targetAmount) {
                    return i;
                }
            }
        }
        
        return 0;
    }

    // ============ ADMIN FUNCTIONS ============

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // Prevent transfers when paused
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal override whenNotPaused {
        super._beforeTokenTransfer(from, to, amount);
    }

    /**
     * @notice Decimals = 18 (1 token = 1 tonne CO2)
     */
    function decimals() public pure override returns (uint8) {
        return 18;
    }
}

contracts/core/CarbonMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "./CarbonCreditToken.sol";
import "./CarbonCreditNFT.sol";

/**
 * @title CarbonMarketplace
 * @notice Hybrid order book + AMM for carbon credit trading
 * @dev Supports both OTC enterprise trades and retail liquidity pools
 * 
 * Features:
 * - Order book for large OTC trades (enterprises)
 * - AMM pool for retail liquidity
 * - KYC gating for compliance trades
 * - Scheduled bulk purchases (Chainlink Automation)
 * - Compliance retirement tracking
 */
contract CarbonMarketplace is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ============ ROLES ============
    bytes32 public constant MATCHER_ROLE = keccak256("MATCHER_ROLE");
    bytes32 public constant KYC_ROLE = keccak256("KYC_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    // ============ STATE VARIABLES ============
    
    /// @notice Supported payment token (USDC/USDT)
    IERC20 public immutable paymentToken;
    
    /// @notice Carbon credit token being traded
    CarbonCreditToken public immutable carbonToken;
    
    /// @notice NFT contract for direct NFT trades
    CarbonCreditNFT public immutable nftContract;

    /// @notice Order structure
    struct Order {
        uint256 orderId;
        address trader;
        bool isBuyOrder;          // true = buy, false = sell
        uint256 amount;           // CCT tokens or NFT count
        uint256 pricePerTonne;    // in payment token (6 decimals for USDC)
        uint256 filled;           // amount filled
        bool isActive;
        uint256 createdAt;
        uint256 expiresAt;
        bool requiresKYC;         // for compliance trades
    }

    /// @notice AMM pool state
    struct Pool {
        uint256 carbonReserve;    // CCT balance
        uint256 stableReserve;    // USDC balance
        uint256 totalLPTokens;    // Liquidity provider tokens
        uint256 lastPrice;        // Last trade price
        uint256 lastUpdate;
    }

    // ============ MAPPINGS ============
    mapping(uint256 => Order) public orders;
    mapping(address => bool) public kycVerified;
    mapping(address => uint256) public lpTokens;       // LP token balances
    mapping(address => uint256[]) public userOrders;   // user => orderIds

    Pool public ammPool;
    uint256 public nextOrderId = 1;
    uint256 public tradingFeePercent = 25;  // 0.25% (in basis points)
    uint256 public constant FEE_DENOMINATOR = 10000;

    // ============ EVENTS ============
    event OrderCreated(
        uint256 indexed orderId,
        address indexed trader,
        bool isBuyOrder,
        uint256 amount,
        uint256 pricePerTonne
    );

    event OrderFilled(
        uint256 indexed orderId,
        address indexed taker,
        uint256 amountFilled,
        uint256 totalCost
    );

    event OrderCancelled(uint256 indexed orderId);

    event LiquidityAdded(
        address indexed provider,
        uint256 carbonAmount,
        uint256 stableAmount,
        uint256 lpTokens
    );

    event LiquidityRemoved(
        address indexed provider,
        uint256 carbonAmount,
        uint256 stableAmount,
        uint256 lpTokens
    );

    event Swap(
        address indexed trader,
        bool carbonToStable,
        uint256 amountIn,
        uint256 amountOut,
        uint256 fee
    );

    event KYCStatusUpdated(address indexed user, bool status);

    // ============ CONSTRUCTOR ============
    constructor(
        address paymentToken_,
        address carbonToken_,
        address nftContract_
    ) {
        require(paymentToken_ != address(0), "Invalid payment token");
        require(carbonToken_ != address(0), "Invalid carbon token");
        require(nftContract_ != address(0), "Invalid NFT contract");

        paymentToken = IERC20(paymentToken_);
        carbonToken = CarbonCreditToken(carbonToken_);
        nftContract = CarbonCreditNFT(nftContract_);

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MATCHER_ROLE, msg.sender);
        _grantRole(KYC_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
    }

    // ============ ORDER BOOK FUNCTIONS ============

    /**
     * @notice Create a buy order (bid)
     * @param amount CCT tokens to buy
     * @param pricePerTonne Price per tonne in payment token
     * @param expiresIn Seconds until order expires (0 = never)
     * @param requiresKYC_ If true, only KYC users can fill
     */
    function createBuyOrder(
        uint256 amount,
        uint256 pricePerTonne,
        uint256 expiresIn,
        bool requiresKYC_
    ) external whenNotPaused nonReentrant returns (uint256 orderId) {
        require(amount > 0, "Invalid amount");
        require(pricePerTonne > 0, "Invalid price");

        if (requiresKYC_) {
            require(kycVerified[msg.sender], "KYC required");
        }

        uint256 totalCost = (amount * pricePerTonne) / 1e18;
        paymentToken.safeTransferFrom(msg.sender, address(this), totalCost);

        orderId = nextOrderId++;
        uint256 expiresAt = expiresIn > 0 ? block.timestamp + expiresIn : type(uint256).max;

        orders[orderId] = Order({
            orderId: orderId,
            trader: msg.sender,
            isBuyOrder: true,
            amount: amount,
            pricePerTonne: pricePerTonne,
            filled: 0,
            isActive: true,
            createdAt: block.timestamp,
            expiresAt: expiresAt,
            requiresKYC: requiresKYC_
        });

        userOrders[msg.sender].push(orderId);

        emit OrderCreated(orderId, msg.sender, true, amount, pricePerTonne);

        return orderId;
    }

    /**
     * @notice Create a sell order (ask)
     */
    function createSellOrder(
        uint256 amount,
        uint256 pricePerTonne,
        uint256 expiresIn,
        bool requiresKYC_
    ) external whenNotPaused nonReentrant returns (uint256 orderId) {
        require(amount > 0, "Invalid amount");
        require(pricePerTonne > 0, "Invalid price");

        if (requiresKYC_) {
            require(kycVerified[msg.sender], "KYC required");
        }

        // Lock seller's CCT tokens
        carbonToken.transferFrom(msg.sender, address(this), amount);

        orderId = nextOrderId++;
        uint256 expiresAt = expiresIn > 0 ? block.timestamp + expiresIn : type(uint256).max;

        orders[orderId] = Order({
            orderId: orderId,
            trader: msg.sender,
            isBuyOrder: false,
            amount: amount,
            pricePerTonne: pricePerTonne,
            filled: 0,
            isActive: true,
            createdAt: block.timestamp,
            expiresAt: expiresAt,
            requiresKYC: requiresKYC_
        });

        userOrders[msg.sender].push(orderId);

        emit OrderCreated(orderId, msg.sender, false, amount, pricePerTonne);

        return orderId;
    }

    /**
     * @notice Fill an existing order (taker)
     * @param orderId Order to fill
     * @param amount Amount to fill (can be partial)
     */
    function fillOrder(uint256 orderId, uint256 amount) 
        external 
        whenNotPaused 
        nonReentrant 
    {
        Order storage order = orders[orderId];
        
        require(order.isActive, "Order not active");
        require(block.timestamp < order.expiresAt, "Order expired");
        require(amount > 0 && amount <= (order.amount - order.filled), "Invalid fill amount");

        if (order.requiresKYC) {
            require(kycVerified[msg.sender], "KYC required");
        }

        uint256 totalCost = (amount * order.pricePerTonne) / 1e18;
        uint256 fee = (totalCost * tradingFeePercent) / FEE_DENOMINATOR;

        if (order.isBuyOrder) {
            // Taker is selling CCT to buyer
            carbonToken.transferFrom(msg.sender, order.trader, amount);
            paymentToken.safeTransfer(msg.sender, totalCost - fee);
        } else {
            // Taker is buying CCT from seller
            paymentToken.safeTransferFrom(msg.sender, address(this), totalCost);
            carbonToken.transfer(msg.sender, amount);
            paymentToken.safeTransfer(order.trader, totalCost - fee);
        }

        order.filled += amount;

        if (order.filled == order.amount) {
            order.isActive = false;
        }

        emit OrderFilled(orderId, msg.sender, amount, totalCost);
    }

    /**
     * @notice Cancel an active order
     */
    function cancelOrder(uint256 orderId) external nonReentrant {
        Order storage order = orders[orderId];
        
        require(order.trader == msg.sender, "Not order creator");
        require(order.isActive, "Order not active");

        uint256 unfilled = order.amount - order.filled;

        if (order.isBuyOrder) {
            // Refund locked payment tokens
            uint256 refund = (unfilled * order.pricePerTonne) / 1e18;
            paymentToken.safeTransfer(msg.sender, refund);
        } else {
            // Return locked CCT
            carbonToken.transfer(msg.sender, unfilled);
        }

        order.isActive = false;

        emit OrderCancelled(orderId);
    }

    // ============ AMM FUNCTIONS ============

    /**
     * @notice Add liquidity to AMM pool
     * @param carbonAmount CCT tokens to add
     * @param stableAmount Payment tokens to add
     */
    function addLiquidity(uint256 carbonAmount, uint256 stableAmount) 
        external 
        whenNotPaused 
        nonReentrant 
        returns (uint256 lpMinted) 
    {
        require(carbonAmount > 0 && stableAmount > 0, "Invalid amounts");

        if (ammPool.totalLPTokens == 0) {
            // Initial liquidity
            lpMinted = sqrt(carbonAmount * stableAmount);
            require(lpMinted > 0, "Insufficient liquidity");
        } else {
            // Proportional liquidity
            uint256 lpFromCarbon = (carbonAmount * ammPool.totalLPTokens) / ammPool.carbonReserve;
            uint256 lpFromStable = (stableAmount * ammPool.totalLPTokens) / ammPool.stableReserve;
            lpMinted = lpFromCarbon < lpFromStable ? lpFromCarbon : lpFromStable;
        }

        // Transfer tokens
        carbonToken.transferFrom(msg.sender, address(this), carbonAmount);
        paymentToken.safeTransferFrom(msg.sender, address(this), stableAmount);

        // Update pool
        ammPool.carbonReserve += carbonAmount;
        ammPool.stableReserve += stableAmount;
        ammPool.totalLPTokens += lpMinted;
        ammPool.lastUpdate = block.timestamp;

        // Mint LP tokens
        lpTokens[msg.sender] += lpMinted;

        emit LiquidityAdded(msg.sender, carbonAmount, stableAmount, lpMinted);

        return lpMinted;
    }

    /**
     * @notice Remove liquidity from AMM pool
     * @param lpAmount LP tokens to burn
     */
    function removeLiquidity(uint256 lpAmount) 
        external 
        nonReentrant 
        returns (uint256 carbonAmount, uint256 stableAmount) 
    {
        require(lpAmount > 0 && lpAmount <= lpTokens[msg.sender], "Invalid LP amount");

        carbonAmount = (lpAmount * ammPool.carbonReserve) / ammPool.totalLPTokens;
        stableAmount = (lpAmount * ammPool.stableReserve) / ammPool.totalLPTokens;

        // Update pool
        ammPool.carbonReserve -= carbonAmount;
        ammPool.stableReserve -= stableAmount;
        ammPool.totalLPTokens -= lpAmount;
        ammPool.lastUpdate = block.timestamp;

        // Burn LP tokens
        lpTokens[msg.sender] -= lpAmount;

        // Transfer tokens
        carbonToken.transfer(msg.sender, carbonAmount);
        paymentToken.safeTransfer(msg.sender, stableAmount);

        emit LiquidityRemoved(msg.sender, carbonAmount, stableAmount, lpAmount);

        return (carbonAmount, stableAmount);
    }

    /**
     * @notice Swap tokens via AMM (constant product formula)
     * @param carbonToStable true = sell CCT for USDC, false = buy CCT with USDC
     * @param amountIn Input token amount
     * @param minAmountOut Minimum output (slippage protection)
     */
    function swap(
        bool carbonToStable,
        uint256 amountIn,
        uint256 minAmountOut
    ) external whenNotPaused nonReentrant returns (uint256 amountOut) {
        require(amountIn > 0, "Invalid input");
        require(ammPool.totalLPTokens > 0, "No liquidity");

        uint256 fee = (amountIn * tradingFeePercent) / FEE_DENOMINATOR;
        uint256 amountInAfterFee = amountIn - fee;

        if (carbonToStable) {
            // Sell CCT for USDC
            amountOut = (amountInAfterFee * ammPool.stableReserve) / 
                        (ammPool.carbonReserve + amountInAfterFee);
            
            require(amountOut >= minAmountOut, "Slippage exceeded");
            require(amountOut < ammPool.stableReserve, "Insufficient liquidity");

            carbonToken.transferFrom(msg.sender, address(this), amountIn);
            paymentToken.safeTransfer(msg.sender, amountOut);

            ammPool.carbonReserve += amountIn;
            ammPool.stableReserve -= amountOut;
        } else {
            // Buy CCT with USDC
            amountOut = (amountInAfterFee * ammPool.carbonReserve) / 
                        (ammPool.stableReserve + amountInAfterFee);
            
            require(amountOut >= minAmountOut, "Slippage exceeded");
            require(amountOut < ammPool.carbonReserve, "Insufficient liquidity");

            paymentToken.safeTransferFrom(msg.sender, address(this), amountIn);
            carbonToken.transfer(msg.sender, amountOut);

            ammPool.stableReserve += amountIn;
            ammPool.carbonReserve -= amountOut;
        }

        ammPool.lastPrice = (ammPool.stableReserve * 1e18) / ammPool.carbonReserve;
        ammPool.lastUpdate = block.timestamp;

        emit Swap(msg.sender, carbonToStable, amountIn, amountOut, fee);

        return amountOut;
    }

    // ============ VIEW FUNCTIONS ============

    function getPrice() external view returns (uint256) {
        if (ammPool.carbonReserve == 0) return 0;
        return (ammPool.stableReserve * 1e18) / ammPool.carbonReserve;
    }

    function getOrder(uint256 orderId) external view returns (Order memory) {
        return orders[orderId];
    }

    function getUserOrders(address user) external view returns (uint256[] memory) {
        return userOrders[user];
    }

    // ============ ADMIN FUNCTIONS ============

    function setKYCStatus(address user, bool status) external onlyRole(KYC_ROLE) {
        kycVerified[user] = status;
        emit KYCStatusUpdated(user, status);
    }

    function setTradingFee(uint256 newFeePercent) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newFeePercent <= 100, "Fee too high"); // Max 1%
        tradingFeePercent = newFeePercent;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // ============ UTILITIES ============

    function sqrt(uint256 x) private pure returns (uint256) {
        if (x == 0) return 0;
        uint256 z = (x + 1) / 2;
        uint256 y = x;
        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }
        return y;
    }
}

contracts/interfaces/ICarbonCreditNFT.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ICarbonCreditNFT
 * @notice Interface for CarbonCreditNFT contract
 */
interface ICarbonCreditNFT {
    struct CarbonCredit {
        string projectId;
        string projectName;
        string methodology;
        uint256 co2Tonnes;
        uint256 vintageYear;
        string geography;
        bytes32 oracleProofHash;
        string satelliteDataCID;
        address verificationSource;
        uint256 verificationDate;
        bool isRetired;
        uint256 issuanceDate;
        string serialNumber;
    }

    struct RetirementCertificate {
        uint256 originalTokenId;
        address retiredBy;
        uint256 retirementDate;
        string retirementReason;
        uint256 co2Tonnes;
    }

    // Events
    event CreditMinted(
        uint256 indexed tokenId,
        string indexed projectId,
        address indexed recipient,
        uint256 co2Tonnes,
        string methodology
    );

    event CreditRetired(
        uint256 indexed tokenId,
        address indexed retiredBy,
        uint256 timestamp,
        uint256 co2Tonnes,
        string reason
    );

    // Core Functions
    function mintCredit(
        address to,
        string memory projectId,
        string memory projectName,
        string memory serialNumber,
        string memory methodology,
        uint256 co2Tonnes,
        uint256 vintageYear,
        string memory geography,
        bytes32 oracleProofHash,
        string memory satelliteDataCID,
        string memory tokenURI
    ) external returns (uint256);

    function retireCredit(uint256 tokenId, string memory reason) external;

    function batchRetire(uint256[] calldata tokenIds, string memory reason) external;

    // View Functions
    function getCreditDetails(uint256 tokenId) external view returns (CarbonCredit memory);

    function getRetirementCertificate(uint256 tokenId) 
        external 
        view 
        returns (RetirementCertificate memory);

    function getGlobalStats() 
        external 
        view 
        returns (
            uint256 minted,
            uint256 retired,
            uint256 active,
            uint256 totalTokens
        );

    function isSerialTokenized(string memory methodology, string memory serialNumber) 
        external 
        view 
        returns (bool);
}

contracts/interfaces/ICarbonCreditToken..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title ICarbonCreditToken
 * @notice Interface for CarbonCreditToken (ERC-20 wrapper)
 */
interface ICarbonCreditToken is IERC20 {
    
    event CreditWrapped(
        address indexed user,
        uint256 indexed tokenId,
        uint256 co2Tonnes
    );

    event CreditUnwrapped(
        address indexed user,
        uint256 indexed tokenId,
        uint256 co2Tonnes
    );

    function wrapCredit(uint256 tokenId) external returns (uint256 tonnesMinted);

    function batchWrap(uint256[] calldata tokenIds) external returns (uint256 totalMinted);

    function unwrapCredit(uint256 tokenId) external returns (uint256 tonnesBurned);

    function unwrapAny(uint256 amount) external returns (uint256 tokenId);

    function getUserWrappedNFTs(address user) external view returns (uint256[] memory);

    function getBackingInfo() 
        external 
        view 
        returns (
            uint256 nftsLocked,
            uint256 tonnesLocked,
            uint256 tokensCirculating
        );

    function isFullyBacked() external view returns (bool);

    function nftContract() external view returns (address);

    function methodology() external view returns (string memory);
}

contracts/interfaces/ICarbonMarketplace..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ICarbonMarketplace
 * @notice Interface for CarbonMarketplace
 */
interface ICarbonMarketplace {
    
    struct Order {
        uint256 orderId;
        address trader;
        bool isBuyOrder;
        uint256 amount;
        uint256 pricePerTonne;
        uint256 filled;
        bool isActive;
        uint256 createdAt;
        uint256 expiresAt;
        bool requiresKYC;
    }

    struct Pool {
        uint256 carbonReserve;
        uint256 stableReserve;
        uint256 totalLPTokens;
        uint256 lastPrice;
        uint256 lastUpdate;
    }

    // Events
    event OrderCreated(
        uint256 indexed orderId,
        address indexed trader,
        bool isBuyOrder,
        uint256 amount,
        uint256 pricePerTonne
    );

    event OrderFilled(
        uint256 indexed orderId,
        address indexed taker,
        uint256 amountFilled,
        uint256 totalCost
    );

    event Swap(
        address indexed trader,
        bool carbonToStable,
        uint256 amountIn,
        uint256 amountOut,
        uint256 fee
    );

    // Order Book Functions
    function createBuyOrder(
        uint256 amount,
        uint256 pricePerTonne,
        uint256 expiresIn,
        bool requiresKYC_
    ) external returns (uint256 orderId);

    function createSellOrder(
        uint256 amount,
        uint256 pricePerTonne,
        uint256 expiresIn,
        bool requiresKYC_
    ) external returns (uint256 orderId);

    function fillOrder(uint256 orderId, uint256 amount) external;

    function cancelOrder(uint256 orderId) external;

    // AMM Functions
    function addLiquidity(uint256 carbonAmount, uint256 stableAmount) 
        external 
        returns (uint256 lpMinted);

    function removeLiquidity(uint256 lpAmount) 
        external 
        returns (uint256 carbonAmount, uint256 stableAmount);

    function swap(
        bool carbonToStable,
        uint256 amountIn,
        uint256 minAmountOut
    ) external returns (uint256 amountOut);

    // View Functions
    function getPrice() external view returns (uint256);

    function getOrder(uint256 orderId) external view returns (Order memory);

    function getUserOrders(address user) external view returns (uint256[] memory);

    function ammPool() external view returns (Pool memory);
}

