contracts/oracle/CarbonPriceOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/functions/dev/v1_0_0/FunctionsClient.sol";
import "@chainlink/contracts/src/v0.8/functions/dev/v1_0_0/libraries/FunctionsRequest.sol";
import "@chainlink/contracts/src/v0.8/automation/AutomationCompatible.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title CarbonPriceOracle
 * @notice Decentralized price feed for carbon credits
 * @dev Aggregates prices from multiple exchanges using Chainlink Functions
 * 
 * Price Sources:
 * - ICM (India Carbon Market) - BEE/CERC data
 * - Verra Spot Prices
 * - ACX (AirCarbon Exchange)
 * - CTX (Climate Trade Exchange)
 * - Xpansiv CBL Futures
 * 
 * Updates: Hourly (off-peak), Every 15 min (high volatility)
 */
contract CarbonPriceOracle is 
    FunctionsClient,
    AutomationCompatibleInterface,
    AccessControl 
{
    using FunctionsRequest for FunctionsRequest.Request;

    // ============ ROLES ============
    bytes32 public constant PRICE_UPDATER_ROLE = keccak256("PRICE_UPDATER_ROLE");
    bytes32 public constant AUTOMATION_ROLE = keccak256("AUTOMATION_ROLE");

    // ============ STATE VARIABLES ============
    
    address public functionsRouter;
    bytes32 public donId;
    uint64 public subscriptionId;
    uint32 public gasLimit = 250000;

    /// @notice Price data structure
    struct PriceData {
        uint256 price;              // Price per tonne in USD (8 decimals)
        uint256 timestamp;
        uint256 volume24h;          // 24h trading volume
        uint8 confidence;           // 0-100 confidence score
        uint256 dataPoints;         // Number of exchanges aggregated
    }

    /// @notice Methodology-specific pricing
    mapping(string => PriceData) public prices;      // "VERRA_VCS" => price
    mapping(string => PriceData[]) public priceHistory;
    
    string[] public methodologies = ["ICM_COMPLIANCE", "VERRA_VCS", "GOLD_STANDARD"];
    
    uint256 public updateInterval = 1 hours;
    uint256 public lastUpdateTime;
    uint256 public highVolatilityThreshold = 10; // 10% price change triggers fast updates

    // ============ CHAINLINK FUNCTIONS SOURCE CODE ============
    
    string public priceFetcherSource = 
        "const methodology = args[0];"
        ""
        "// Fetch from multiple exchanges"
        "const sources = ["
        "  { name: 'ACX', url: 'https://api.aircarbon.co/v1/prices', weight: 0.3 },"
        "  { name: 'CTX', url: 'https://api.climatetrade.com/v1/prices', weight: 0.2 },"
        "  { name: 'ICM', url: 'https://cerc.gov.in/api/carbon-prices', weight: 0.5 }"
        "];"
        ""
        "const promises = sources.map(source => "
        "  Functions.makeHttpRequest({"
        "    url: `${source.url}/${methodology}`,"
        "    headers: { 'Authorization': `Bearer ${secrets.EXCHANGE_API_KEY}` }"
        "  }).catch(err => ({ error: true, source: source.name }))"
        ");"
        ""
        "const responses = await Promise.all(promises);"
        ""
        "// Calculate volume-weighted average price (VWAP)"
        "let totalPrice = 0;"
        "let totalWeight = 0;"
        "let totalVolume = 0;"
        "let validSources = 0;"
        ""
        "for (let i = 0; i < responses.length; i++) {"
        "  if (!responses[i].error && responses[i].data) {"
        "    const price = parseFloat(responses[i].data.price);"
        "    const volume = parseFloat(responses[i].data.volume_24h || 0);"
        "    const weight = sources[i].weight;"
        "    "
        "    totalPrice += price * weight;"
        "    totalWeight += weight;"
        "    totalVolume += volume;"
        "    validSources++;"
        "  }"
        "}"
        ""
        "if (validSources === 0) {"
        "  throw Error('No valid price sources');"
        "}"
        ""
        "const avgPrice = totalPrice / totalWeight;"
        "const confidence = Math.round((validSources / sources.length) * 100);"
        ""
        "// Encode: [price (8 decimals) | volume (8 decimals) | confidence (uint8)]"
        "const priceScaled = Math.round(avgPrice * 1e8);"
        "const volumeScaled = Math.round(totalVolume * 1e8);"
        ""
        "// Pack into single uint256: [price (128 bits) | volume (120 bits) | confidence (8 bits)]"
        "const result = (BigInt(priceScaled) << 128n) | (BigInt(volumeScaled) << 8n) | BigInt(confidence);"
        ""
        "return Functions.encodeUint256(result);";

    // ============ EVENTS ============
    event PriceUpdated(
        string indexed methodology,
        uint256 price,
        uint256 volume24h,
        uint8 confidence,
        uint256 timestamp
    );

    event HighVolatilityDetected(
        string indexed methodology,
        uint256 oldPrice,
        uint256 newPrice,
        uint256 changePercent
    );

    event PriceRequestFailed(string indexed methodology, string reason);

    // ============ CONSTRUCTOR ============
    constructor(address functionsRouter_) FunctionsClient(functionsRouter_) {
        functionsRouter = functionsRouter_;
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PRICE_UPDATER_ROLE, msg.sender);
    }

    // ============ CHAINLINK AUTOMATION ============

    function checkUpkeep(bytes calldata /* checkData */)
        external
        view
        override
        returns (bool upkeepNeeded, bytes memory performData)
    {
        upkeepNeeded = (block.timestamp - lastUpdateTime) >= updateInterval;
        performData = "";
    }

    function performUpkeep(bytes calldata /* performData */) 
        external 
        override 
        onlyRole(AUTOMATION_ROLE)
    {
        _updateAllPrices();
    }

    // ============ PRICE UPDATE FUNCTIONS ============

    function updatePrice(string memory methodology) 
        external 
        onlyRole(PRICE_UPDATER_ROLE) 
    {
        _requestPriceUpdate(methodology);
    }

    function updateAllPrices() external onlyRole(PRICE_UPDATER_ROLE) {
        _updateAllPrices();
    }

    function _updateAllPrices() internal {
        for (uint256 i = 0; i < methodologies.length; i++) {
            _requestPriceUpdate(methodologies[i]);
        }
        lastUpdateTime = block.timestamp;
    }

    function _requestPriceUpdate(string memory methodology) internal {
        FunctionsRequest.Request memory req;
        req.initializeRequestForInlineJavaScript(priceFetcherSource);

        string[] memory args = new string[](1);
        args[0] = methodology;
        req.setArgs(args);

        _sendRequest(
            req.encodeCBOR(),
            subscriptionId,
            gasLimit,
            donId
        );
    }

    function fulfillRequest(
        bytes32 /* requestId */,
        bytes memory response,
        bytes memory err
    ) internal override {
        if (err.length > 0) {
            emit PriceRequestFailed("UNKNOWN", string(err));
            return;
        }

        // Decode packed response
        uint256 packed = abi.decode(response, (uint256));
        
        uint256 price = uint256(uint128(packed >> 128));
        uint256 volume = uint256(uint120((packed >> 8) & ((1 << 120) - 1)));
        uint8 confidence = uint8(packed & 0xFF);

        // Determine methodology (simplified - in production, track by requestId)
        string memory methodology = methodologies[0]; // Placeholder
        
        // Check for high volatility
        PriceData memory oldPrice = prices[methodology];
        if (oldPrice.price > 0) {
            uint256 changePercent = _calculateChangePercent(oldPrice.price, price);
            if (changePercent >= highVolatilityThreshold) {
                emit HighVolatilityDetected(methodology, oldPrice.price, price, changePercent);
                updateInterval = 15 minutes; // Switch to fast updates
            } else if (updateInterval < 1 hours) {
                updateInterval = 1 hours; // Return to normal cadence
            }
        }

        // Update price
        prices[methodology] = PriceData({
            price: price,
            timestamp: block.timestamp,
            volume24h: volume,
            confidence: confidence,
            dataPoints: 3 // Number of exchanges (hardcoded for now)
        });

        // Store in history
        priceHistory[methodology].push(prices[methodology]);

        emit PriceUpdated(methodology, price, volume, confidence, block.timestamp);
    }

    // ============ VIEW FUNCTIONS ============

    function getPrice(string memory methodology) 
        external 
        view 
        returns (uint256 price, uint256 timestamp) 
    {
        PriceData memory data = prices[methodology];
        return (data.price, data.timestamp);
    }

    function getPriceData(string memory methodology) 
        external 
        view 
        returns (PriceData memory) 
    {
        return prices[methodology];
    }

    function getPriceHistory(string memory methodology, uint256 limit) 
        external 
        view 
        returns (PriceData[] memory) 
    {
        uint256 length = priceHistory[methodology].length;
        uint256 resultLength = limit < length ? limit : length;
        
        PriceData[] memory result = new PriceData[](resultLength);
        
        for (uint256 i = 0; i < resultLength; i++) {
            result[i] = priceHistory[methodology][length - resultLength + i];
        }
        
        return result;
    }

    function getLatestPrice(string memory methodology) 
        external 
        view 
        returns (uint256) 
    {
        require(prices[methodology].timestamp > 0, "Price not available");
        require(block.timestamp - prices[methodology].timestamp < 24 hours, "Price too stale");
        return prices[methodology].price;
    }

    // ============ ADMIN FUNCTIONS ============

    function setFunctionsConfig(
        bytes32 donId_,
        uint64 subscriptionId_,
        uint32 gasLimit_
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        donId = donId_;
        subscriptionId = subscriptionId_;
        gasLimit = gasLimit_;
    }

    function setUpdateInterval(uint256 interval) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        require(interval >= 5 minutes && interval <= 24 hours, "Invalid interval");
        updateInterval = interval;
    }

    function setVolatilityThreshold(uint256 threshold) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        require(threshold > 0 && threshold <= 50, "Invalid threshold");
        highVolatilityThreshold = threshold;
    }

    function grantAutomationRole(address automationRegistry) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        _grantRole(AUTOMATION_ROLE, automationRegistry);
    }

    // ============ UTILITIES ============

    function _calculateChangePercent(uint256 oldPrice, uint256 newPrice) 
        internal 
        pure 
        returns (uint256) 
    {
        if (oldPrice == 0) return 0;
        
        uint256 diff = oldPrice > newPrice ? oldPrice - newPrice : newPrice - oldPrice;
        return (diff * 100) / oldPrice;
    }
}

contracts/oracle/EmissionVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/functions/dev/v1_0_0/FunctionsClient.sol";
import "@chainlink/contracts/src/v0.8/functions/dev/v1_0_0/libraries/FunctionsRequest.sol";
import "@chainlink/contracts/src/v0.8/automation/AutomationCompatible.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "../core/CarbonCreditNFT.sol";

/**
 * @title EmissionVerifier
 * @notice Oracle-powered emission verification using Chainlink Functions + Automation
 * @dev Fetches IoT sensor data, satellite imagery, and auditor reports to verify carbon credits
 * 
 * Architecture:
 * 1. Project registers with baseline emission data
 * 2. Chainlink Automation triggers periodic verification (monthly/quarterly)
 * 3. Chainlink Functions aggregates multi-source emission data
 * 4. Smart contract validates reduction and mints credits
 * 
 * Data Sources:
 * - IoT sensors (MQTT broker)
 * - Copernicus satellite API
 * - ACVA auditor signatures
 * - BEE MRV Portal (India compliance)
 */
contract EmissionVerifier is 
    FunctionsClient,
    AutomationCompatibleInterface,
    AccessControl,
    ReentrancyGuard 
{
    using FunctionsRequest for FunctionsRequest.Request;

    // ============ ROLES ============
    bytes32 public constant PROJECT_REGISTRAR_ROLE = keccak256("PROJECT_REGISTRAR_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant AUTOMATION_ROLE = keccak256("AUTOMATION_ROLE");

    // ============ STATE VARIABLES ============
    
    /// @notice Chainlink Functions configuration
    address public functionsRouter;
    bytes32 public donId;
    uint64 public subscriptionId;
    uint32 public gasLimit = 300000;
    
    /// @notice Carbon credit NFT contract
    CarbonCreditNFT public immutable nftContract;
    
    /// @notice Project verification state
    struct Project {
        string projectId;
        address owner;
        string methodology;           // "ICM_COMPLIANCE" | "VERRA_VCS" | "GOLD_STANDARD"
        uint256 baselineEmissions;    // Annual baseline in tonnes CO2
        uint256 targetReduction;      // Target reduction percentage (e.g., 30 = 30%)
        uint256 lastVerificationTime;
        uint256 verificationInterval; // Seconds between verifications (30 days default)
        bool isActive;
        string iotEndpoint;           // IoT sensor API endpoint
        string satelliteRegion;       // Lat/lon for satellite data
        bytes32 auditorSignature;     // ACVA digital signature
    }
    
    /// @notice Verification request tracking
    struct VerificationRequest {
        bytes32 requestId;
        string projectId;
        uint256 requestTime;
        bool fulfilled;
        uint256 measuredEmissions;    // Actual emissions measured
        uint256 reductionAchieved;    // Reduction vs baseline
        bytes32 dataProofHash;        // IPFS CID of raw data
        uint8 confidenceScore;        // 0-100 confidence level
    }

    // ============ MAPPINGS ============
    mapping(string => Project) public projects;
    mapping(bytes32 => VerificationRequest) public verificationRequests;
    mapping(string => bytes32[]) public projectRequests;      // projectId => requestIds
    mapping(string => uint256) public projectCreditsMinted;   // projectId => total tonnes
    
    string[] public activeProjects;                           // For Automation upkeep
    mapping(string => bool) public isProjectIndexed;

    // ============ CHAINLINK FUNCTIONS SOURCE CODE ============
    
    /// @notice JavaScript source code executed by Chainlink DON
    /// @dev This fetches data from multiple sources and aggregates
    string public emissionFetcherSource = 
        "const projectId = args[0];"
        "const iotEndpoint = args[1];"
        "const satelliteRegion = args[2];"
        ""
        "// Fetch IoT sensor data"
        "const iotResponse = await Functions.makeHttpRequest({"
        "  url: `${iotEndpoint}/emissions/${projectId}`,"
        "  headers: { 'Authorization': `Bearer ${secrets.IOT_API_KEY}` }"
        "});"
        ""
        "if (iotResponse.error) {"
        "  throw Error('IoT fetch failed');"
        "}"
        ""
        "// Fetch Copernicus satellite data"
        "const [lat, lon] = satelliteRegion.split(',');"
        "const satResponse = await Functions.makeHttpRequest({"
        "  url: 'https://ads.atmosphere.copernicus.eu/api/v2/resources/satellite-carbon-dioxide',"
        "  params: {"
        "    latitude: lat,"
        "    longitude: lon,"
        "    start: new Date(Date.now() - 30*24*60*60*1000).toISOString(),"
        "    end: new Date().toISOString()"
        "  },"
        "  headers: { 'Authorization': `Bearer ${secrets.COPERNICUS_KEY}` }"
        "});"
        ""
        "if (satResponse.error) {"
        "  throw Error('Satellite fetch failed');"
        "}"
        ""
        "// Aggregate emissions data"
        "const iotEmissions = iotResponse.data.total_co2_tonnes;"
        "const satelliteFlux = satResponse.data.mean_co2_flux;"
        ""
        "// Cross-validate (flag if >15% discrepancy)"
        "const discrepancy = Math.abs(iotEmissions - satelliteFlux) / iotEmissions;"
        "if (discrepancy > 0.15) {"
        "  throw Error(`Data mismatch: ${(discrepancy*100).toFixed(1)}% difference`);"
        "}"
        ""
        "// Calculate confidence score"
        "const confidence = Math.round(100 * (1 - discrepancy));"
        ""
        "// Return aggregated data (uint256 format)"
        "const emissions = Math.round(iotEmissions * 1e18);"
        "const conf = confidence;"
        ""
        "return Functions.encodeUint256(emissions);";

    // ============ EVENTS ============
    event ProjectRegistered(
        string indexed projectId,
        address indexed owner,
        uint256 baselineEmissions,
        uint256 targetReduction
    );

    event VerificationRequested(
        bytes32 indexed requestId,
        string indexed projectId,
        uint256 requestTime
    );

    event VerificationFulfilled(
        bytes32 indexed requestId,
        string indexed projectId,
        uint256 measuredEmissions,
        uint256 reductionAchieved,
        uint8 confidenceScore
    );

    event CreditsMinted(
        string indexed projectId,
        address indexed owner,
        uint256 amount,
        uint256 tokenId
    );

    event ProjectDeactivated(string indexed projectId, string reason);

    event SourceCodeUpdated(uint256 timestamp);

    // ============ CONSTRUCTOR ============
    constructor(
        address functionsRouter_,
        address nftContract_
    ) FunctionsClient(functionsRouter_) {
        require(nftContract_ != address(0), "Invalid NFT contract");
        
        functionsRouter = functionsRouter_;
        nftContract = CarbonCreditNFT(nftContract_);
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PROJECT_REGISTRAR_ROLE, msg.sender);
        _grantRole(VERIFIER_ROLE, msg.sender);
    }

    // ============ PROJECT MANAGEMENT ============

    /**
     * @notice Register a new carbon offset project
     * @dev Only authorized registrars (ACVA, project developers with verification)
     * @param projectId Unique project identifier
     * @param methodology Carbon standard (ICM/Verra/Gold Standard)
     * @param baselineEmissions Annual baseline emissions in tonnes
     * @param targetReduction Target reduction percentage (e.g., 30 for 30%)
     * @param verificationInterval Seconds between verifications (default 30 days)
     * @param iotEndpoint IoT sensor API endpoint
     * @param satelliteRegion "lat,lon" for satellite monitoring
     * @param auditorSignature ACVA digital signature
     */
    function registerProject(
        string memory projectId,
        address owner,
        string memory methodology,
        uint256 baselineEmissions,
        uint256 targetReduction,
        uint256 verificationInterval,
        string memory iotEndpoint,
        string memory satelliteRegion,
        bytes32 auditorSignature
    ) external onlyRole(PROJECT_REGISTRAR_ROLE) {
        require(bytes(projectId).length > 0, "Invalid project ID");
        require(owner != address(0), "Invalid owner");
        require(baselineEmissions > 0, "Invalid baseline");
        require(targetReduction > 0 && targetReduction <= 100, "Invalid target");
        require(!projects[projectId].isActive, "Project already registered");

        projects[projectId] = Project({
            projectId: projectId,
            owner: owner,
            methodology: methodology,
            baselineEmissions: baselineEmissions,
            targetReduction: targetReduction,
            lastVerificationTime: block.timestamp,
            verificationInterval: verificationInterval > 0 ? verificationInterval : 30 days,
            isActive: true,
            iotEndpoint: iotEndpoint,
            satelliteRegion: satelliteRegion,
            auditorSignature: auditorSignature
        });

        if (!isProjectIndexed[projectId]) {
            activeProjects.push(projectId);
            isProjectIndexed[projectId] = true;
        }

        emit ProjectRegistered(projectId, owner, baselineEmissions, targetReduction);
    }

    /**
     * @notice Deactivate a project (e.g., project completed, fraud detected)
     */
    function deactivateProject(string memory projectId, string memory reason) 
        external 
        onlyRole(VERIFIER_ROLE) 
    {
        require(projects[projectId].isActive, "Project not active");
        projects[projectId].isActive = false;
        
        emit ProjectDeactivated(projectId, reason);
    }

    // ============ CHAINLINK AUTOMATION (SCHEDULED VERIFICATION) ============

    /**
     * @notice Chainlink Automation calls this to check if verification is needed
     * @dev Checks all active projects for verification interval expiry
     */
    function checkUpkeep(bytes calldata /* checkData */)
        external
        view
        override
        returns (bool upkeepNeeded, bytes memory performData)
    {
        string[] memory projectsToVerify = new string[](activeProjects.length);
        uint256 count = 0;

        for (uint256 i = 0; i < activeProjects.length; i++) {
            string memory projectId = activeProjects[i];
            Project memory project = projects[projectId];

            if (project.isActive && 
                (block.timestamp - project.lastVerificationTime) >= project.verificationInterval) {
                projectsToVerify[count] = projectId;
                count++;
            }
        }

        if (count > 0) {
            // Resize array to actual count
            string[] memory result = new string[](count);
            for (uint256 i = 0; i < count; i++) {
                result[i] = projectsToVerify[i];
            }
            
            upkeepNeeded = true;
            performData = abi.encode(result);
        } else {
            upkeepNeeded = false;
            performData = "";
        }
    }

    /**
     * @notice Chainlink Automation calls this to perform verification
     * @dev Triggers Chainlink Functions requests for all projects due for verification
     */
    function performUpkeep(bytes calldata performData) 
        external 
        override 
        onlyRole(AUTOMATION_ROLE)
    {
        string[] memory projectsToVerify = abi.decode(performData, (string[]));
        
        for (uint256 i = 0; i < projectsToVerify.length; i++) {
            _requestVerification(projectsToVerify[i]);
        }
    }

    // ============ CHAINLINK FUNCTIONS (DATA FETCHING) ============

    /**
     * @notice Manually trigger verification (for testing or on-demand verification)
     */
    function requestVerification(string memory projectId) 
        external 
        onlyRole(VERIFIER_ROLE) 
    {
        _requestVerification(projectId);
    }

    /**
     * @notice Internal function to request emission data via Chainlink Functions
     */
    function _requestVerification(string memory projectId) 
        internal 
        nonReentrant 
    {
        Project storage project = projects[projectId];
        require(project.isActive, "Project not active");

        // Prepare Chainlink Functions request
        FunctionsRequest.Request memory req;
        req.initializeRequestForInlineJavaScript(emissionFetcherSource);

        // Set arguments
        string[] memory args = new string[](3);
        args[0] = projectId;
        args[1] = project.iotEndpoint;
        args[2] = project.satelliteRegion;
        req.setArgs(args);

        // Send request to Chainlink DON
        bytes32 requestId = _sendRequest(
            req.encodeCBOR(),
            subscriptionId,
            gasLimit,
            donId
        );

        // Track request
        verificationRequests[requestId] = VerificationRequest({
            requestId: requestId,
            projectId: projectId,
            requestTime: block.timestamp,
            fulfilled: false,
            measuredEmissions: 0,
            reductionAchieved: 0,
            dataProofHash: bytes32(0),
            confidenceScore: 0
        });

        projectRequests[projectId].push(requestId);

        emit VerificationRequested(requestId, projectId, block.timestamp);
    }

    /**
     * @notice Chainlink Functions callback - receives emission data
     * @dev Automatically called by Chainlink DON after data aggregation
     */
    function fulfillRequest(
        bytes32 requestId,
        bytes memory response,
        bytes memory err
    ) internal override {
        VerificationRequest storage request = verificationRequests[requestId];
        require(!request.fulfilled, "Request already fulfilled");

        if (err.length > 0) {
            // Oracle error - flag for manual review
            emit VerificationFulfilled(requestId, request.projectId, 0, 0, 0);
            return;
        }

        // Decode response (uint256 encoded emissions)
        uint256 measuredEmissions = abi.decode(response, (uint256));
        
        Project storage project = projects[request.projectId];
        
        // Calculate reduction
        uint256 reductionAchieved = 0;
        if (measuredEmissions < project.baselineEmissions) {
            reductionAchieved = project.baselineEmissions - measuredEmissions;
        }

        // Calculate confidence score (simplified - in production, parse from response)
        uint8 confidenceScore = 95; // Placeholder

        // Update request
        request.fulfilled = true;
        request.measuredEmissions = measuredEmissions;
        request.reductionAchieved = reductionAchieved;
        request.confidenceScore = confidenceScore;
        request.dataProofHash = keccak256(response); // In production, store IPFS CID

        // Update project
        project.lastVerificationTime = block.timestamp;

        emit VerificationFulfilled(
            requestId,
            request.projectId,
            measuredEmissions,
            reductionAchieved,
            confidenceScore
        );

        // Auto-mint credits if reduction meets target and confidence is high
        if (confidenceScore >= 90 && reductionAchieved > 0) {
            _mintCreditsForProject(request.projectId, reductionAchieved, requestId);
        }
    }

    /**
     * @notice Mint carbon credits based on verified emission reduction
     */
    function _mintCreditsForProject(
        string memory projectId,
        uint256 reductionTonnes,
        bytes32 requestId
    ) internal {
        Project memory project = projects[projectId];
        
        // Prepare metadata
        string memory tokenURI = string(abi.encodePacked(
            "ipfs://Qm", // Placeholder - in production, upload to IPFS
            projectId
        ));

        string memory serialNumber = string(abi.encodePacked(
            project.methodology,
            "-",
            projectId,
            "-",
            _toString(block.timestamp)
        ));

        // Mint NFT
        uint256 tokenId = nftContract.mintCredit(
            project.owner,
            projectId,
            projectId, // projectName
            serialNumber,
            project.methodology,
            reductionTonnes * 1e18, // Convert to 18 decimals
            block.timestamp / 365 days + 1970, // Vintage year
            "India", // Geography - make dynamic in production
            requestId, // Oracle proof hash
            "", // Satellite data CID - add in production
            tokenURI
        );

        projectCreditsMinted[projectId] += reductionTonnes;

        emit CreditsMinted(projectId, project.owner, reductionTonnes, tokenId);
    }

    // ============ VIEW FUNCTIONS ============

    function getProject(string memory projectId) 
        external 
        view 
        returns (Project memory) 
    {
        return projects[projectId];
    }

    function getVerificationRequest(bytes32 requestId) 
        external 
        view 
        returns (VerificationRequest memory) 
    {
        return verificationRequests[requestId];
    }

    function getProjectRequests(string memory projectId) 
        external 
        view 
        returns (bytes32[] memory) 
    {
        return projectRequests[projectId];
    }

    function getActiveProjectCount() external view returns (uint256) {
        uint256 count = 0;
        for (uint256 i = 0; i < activeProjects.length; i++) {
            if (projects[activeProjects[i]].isActive) {
                count++;
            }
        }
        return count;
    }

    // ============ ADMIN FUNCTIONS ============

    function setFunctionsConfig(
        bytes32 donId_,
        uint64 subscriptionId_,
        uint32 gasLimit_
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        donId = donId_;
        subscriptionId = subscriptionId_;
        gasLimit = gasLimit_;
    }

    function updateSourceCode(string memory newSource) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        emissionFetcherSource = newSource;
        emit SourceCodeUpdated(block.timestamp);
    }

    function grantAutomationRole(address automationRegistry) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        _grantRole(AUTOMATION_ROLE, automationRegistry);
    }

    // ============ UTILITIES ============

    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }
}

contracts/oracle/RegistrySync.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/functions/dev/v1_0_0/FunctionsClient.sol";
import "@chainlink/contracts/src/v0.8/functions/dev/v1_0_0/libraries/FunctionsRequest.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "../core/CarbonCreditNFT.sol";

/**
 * @title RegistrySync
 * @notice Prevents double-counting by verifying credits against external registries
 * @dev Uses Chainlink Functions to query Verra, Gold Standard, and ICM registries
 * 
 * Problem: Same carbon reduction could be tokenized on multiple platforms
 * Solution: Before minting, verify serial number doesn't exist in external registry
 * 
 * Registries Supported:
 * - Verra Registry (VCS)
 * - Gold Standard Registry
 * - India Carbon Market (ICM/GCI)
 * - ACX (AirCarbon Exchange)
 */
contract RegistrySync is 
    FunctionsClient,
    AccessControl,
    ReentrancyGuard 
{
    using FunctionsRequest for FunctionsRequest.Request;

    // ============ ROLES ============
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    // ============ STATE VARIABLES ============
    
    address public functionsRouter;
    bytes32 public donId;
    uint64 public subscriptionId;
    uint32 public gasLimit = 200000;

    CarbonCreditNFT public immutable nftContract;

    /// @notice Registry verification request
    struct RegistryCheck {
        bytes32 requestId;
        string registry;              // "VERRA" | "GOLD_STANDARD" | "ICM"
        string serialNumber;
        address requester;
        uint256 requestTime;
        bool fulfilled;
        bool existsInRegistry;        // true = already tokenized elsewhere
        string registryStatus;        // "ACTIVE" | "RETIRED" | "NOT_FOUND"
        bytes32 registryProofHash;
    }

    /// @notice Whitelist of verified registries
    struct Registry {
        string name;
        string apiEndpoint;
        bool isActive;
        uint256 checksPerformed;
        uint256 duplicatesFound;
    }

    // ============ MAPPINGS ============
    mapping(bytes32 => RegistryCheck) public registryChecks;
    mapping(string => Registry) public registries;
    mapping(string => mapping(string => bool)) public registrySerials; // registry => serial => exists
    mapping(bytes32 => bool) public verifiedCredits;  // keccak256(registry, serial) => verified

    string[] public registryList;

    // ============ CHAINLINK FUNCTIONS SOURCE CODE ============
    
    string public registryCheckSource = 
        "const registry = args[0];"
        "const serialNumber = args[1];"
        ""
        "let apiUrl, headers;"
        ""
        "// Route to appropriate registry API"
        "if (registry === 'VERRA') {"
        "  apiUrl = `https://registry.verra.org/api/v1/credits/${serialNumber}`;"
        "  headers = { 'Authorization': `Bearer ${secrets.VERRA_API_KEY}` };"
        "} else if (registry === 'GOLD_STANDARD') {"
        "  apiUrl = `https://api.goldstandard.org/registry/credits/${serialNumber}`;"
        "  headers = { 'Authorization': `Bearer ${secrets.GS_API_KEY}` };"
        "} else if (registry === 'ICM') {"
        "  apiUrl = `https://gci.bee.gov.in/api/credits/${serialNumber}`;"
        "  headers = { 'Authorization': `Bearer ${secrets.ICM_API_KEY}` };"
        "} else {"
        "  throw Error('Unsupported registry');"
        "}"
        ""
        "// Query registry"
        "const response = await Functions.makeHttpRequest({"
        "  url: apiUrl,"
        "  headers: headers"
        "});"
        ""
        "if (response.error && response.status !== 404) {"
        "  throw Error(`Registry query failed: ${response.error}`);"
        "}"
        ""
        "// Parse response"
        "let exists = false;"
        "let status = 'NOT_FOUND';"
        ""
        "if (response.status === 200 && response.data) {"
        "  exists = true;"
        "  status = response.data.status || 'ACTIVE';"
        "}"
        ""
        "// Encode result: [exists (bool), status (uint8)]"
        "// Status: 0=NOT_FOUND, 1=ACTIVE, 2=RETIRED"
        "const statusCode = status === 'RETIRED' ? 2 : (status === 'ACTIVE' ? 1 : 0);"
        "const result = (exists ? 1 : 0) * 256 + statusCode;"
        ""
        "return Functions.encodeUint256(result);";

    // ============ EVENTS ============
    event RegistryCheckRequested(
        bytes32 indexed requestId,
        string indexed registry,
        string serialNumber
    );

    event RegistryCheckFulfilled(
        bytes32 indexed requestId,
        string indexed registry,
        string serialNumber,
        bool existsInRegistry,
        string status
    );

    event DuplicateCreditDetected(
        string indexed registry,
        string serialNumber,
        address requester
    );

    event RegistryAdded(string indexed registry, string apiEndpoint);

    event CreditVerified(
        bytes32 indexed creditHash,
        string registry,
        string serialNumber
    );

    // ============ CONSTRUCTOR ============
    constructor(
        address functionsRouter_,
        address nftContract_
    ) FunctionsClient(functionsRouter_) {
        require(nftContract_ != address(0), "Invalid NFT contract");
        
        functionsRouter = functionsRouter_;
        nftContract = CarbonCreditNFT(nftContract_);
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(VERIFIER_ROLE, msg.sender);
        _grantRole(ORACLE_ROLE, msg.sender);

        // Initialize default registries
        _addRegistry("VERRA", "https://registry.verra.org/api/v1");
        _addRegistry("GOLD_STANDARD", "https://api.goldstandard.org/registry");
        _addRegistry("ICM", "https://gci.bee.gov.in/api");
    }

    // ============ CORE FUNCTIONS ============

    /**
     * @notice Check if a serial number exists in external registry
     * @dev Called before minting to prevent double-counting
     * @param registry Registry name ("VERRA", "GOLD_STANDARD", "ICM")
     * @param serialNumber Credit serial number to check
     * @return requestId Chainlink Functions request ID
     */
    function checkRegistry(
        string memory registry,
        string memory serialNumber
    ) external onlyRole(VERIFIER_ROLE) nonReentrant returns (bytes32 requestId) {
        require(registries[registry].isActive, "Registry not supported");
        require(bytes(serialNumber).length > 0, "Invalid serial number");

        // Prepare Chainlink Functions request
        FunctionsRequest.Request memory req;
        req.initializeRequestForInlineJavaScript(registryCheckSource);

        string[] memory args = new string[](2);
        args[0] = registry;
        args[1] = serialNumber;
        req.setArgs(args);

        // Send request
        requestId = _sendRequest(
            req.encodeCBOR(),
            subscriptionId,
            gasLimit,
            donId
        );

        // Track request
        registryChecks[requestId] = RegistryCheck({
            requestId: requestId,
            registry: registry,
            serialNumber: serialNumber,
            requester: msg.sender,
            requestTime: block.timestamp,
            fulfilled: false,
            existsInRegistry: false,
            registryStatus: "",
            registryProofHash: bytes32(0)
        });

        registries[registry].checksPerformed++;

        emit RegistryCheckRequested(requestId, registry, serialNumber);

        return requestId;
    }

    /**
     * @notice Chainlink Functions callback - receives registry check result
     */
    function fulfillRequest(
        bytes32 requestId,
        bytes memory response,
        bytes memory err
    ) internal override {
        RegistryCheck storage check = registryChecks[requestId];
        require(!check.fulfilled, "Request already fulfilled");

        if (err.length > 0) {
            // Oracle error - assume credit doesn't exist (fail-safe)
            check.fulfilled = true;
            check.existsInRegistry = false;
            check.registryStatus = "ERROR";
            emit RegistryCheckFulfilled(requestId, check.registry, check.serialNumber, false, "ERROR");
            return;
        }

        // Decode response: [exists (1 byte) | status (1 byte)]
        uint256 result = abi.decode(response, (uint256));
        bool exists = (result / 256) == 1;
        uint8 statusCode = uint8(result % 256);
        
        string memory status = statusCode == 2 ? "RETIRED" : (statusCode == 1 ? "ACTIVE" : "NOT_FOUND");

        // Update check
        check.fulfilled = true;
        check.existsInRegistry = exists;
        check.registryStatus = status;
        check.registryProofHash = keccak256(response);

        // Update registry tracking
        if (exists) {
            registrySerials[check.registry][check.serialNumber] = true;
            registries[check.registry].duplicatesFound++;
            
            emit DuplicateCreditDetected(check.registry, check.serialNumber, check.requester);
        } else {
            // Mark as verified for minting
            bytes32 creditHash = keccak256(abi.encodePacked(check.registry, check.serialNumber));
            verifiedCredits[creditHash] = true;
            
            emit CreditVerified(creditHash, check.registry, check.serialNumber);
        }

        emit RegistryCheckFulfilled(requestId, check.registry, check.serialNumber, exists, status);
    }

    /**
     * @notice Verify a credit is cleared for minting
     * @dev Called by CarbonCreditNFT before minting
     */
    function isCreditVerified(string memory registry, string memory serialNumber) 
        external 
        view 
        returns (bool) 
    {
        bytes32 creditHash = keccak256(abi.encodePacked(registry, serialNumber));
        return verifiedCredits[creditHash];
    }

    /**
     * @notice Check if serial exists in local cache (fast check before oracle)
     */
    function isSerialUsed(string memory registry, string memory serialNumber) 
        external 
        view 
        returns (bool) 
    {
        // Check local NFT contract
        bool usedLocally = nftContract.isSerialTokenized(registry, serialNumber);
        
        // Check external registry cache
        bool usedExternally = registrySerials[registry][serialNumber];
        
        return usedLocally || usedExternally;
    }

    /**
     * @notice Batch check multiple serials (gas-optimized)
     */
    function batchCheckRegistry(
        string memory registry,
        string[] memory serialNumbers
    ) external onlyRole(VERIFIER_ROLE) returns (bytes32[] memory requestIds) {
        require(serialNumbers.length > 0 && serialNumbers.length <= 20, "Invalid batch size");
        
        requestIds = new bytes32[](serialNumbers.length);
        
        for (uint256 i = 0; i < serialNumbers.length; i++) {
            requestIds[i] = this.checkRegistry(registry, serialNumbers[i]);
        }
        
        return requestIds;
    }

    // ============ ADMIN FUNCTIONS ============

    function addRegistry(string memory name, string memory apiEndpoint) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        _addRegistry(name, apiEndpoint);
    }

    function _addRegistry(string memory name, string memory apiEndpoint) internal {
        require(bytes(name).length > 0, "Invalid registry name");
        
        registries[name] = Registry({
            name: name,
            apiEndpoint: apiEndpoint,
            isActive: true,
            checksPerformed: 0,
            duplicatesFound: 0
        });
        
        registryList.push(name);
        
        emit RegistryAdded(name, apiEndpoint);
    }

    function setRegistryStatus(string memory name, bool isActive) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        registries[name].isActive = isActive;
    }

    function setFunctionsConfig(
        bytes32 donId_,
        uint64 subscriptionId_,
        uint32 gasLimit_
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        donId = donId_;
        subscriptionId = subscriptionId_;
        gasLimit = gasLimit_;
    }

    function updateSourceCode(string memory newSource) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        registryCheckSource = newSource;
    }

    // ============ VIEW FUNCTIONS ============

    function getRegistryCheck(bytes32 requestId) 
        external 
        view 
        returns (RegistryCheck memory) 
    {
        return registryChecks[requestId];
    }

    function getRegistry(string memory name) 
        external 
        view 
        returns (Registry memory) 
    {
        return registries[name];
    }

    function getSupportedRegistries() external view returns (string[] memory) {
        return registryList;
    }

    function getRegistryStats(string memory name) 
        external 
        view 
        returns (
            uint256 checksPerformed,
            uint256 duplicatesFound,
            bool isActive
        ) 
    {
        Registry memory reg = registries[name];
        return (reg.checksPerformed, reg.duplicatesFound, reg.isActive);
    }
}

